<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import DataGrid, { type GridColumn } from "@/components/DataGrid.vue";
import { useAuthSession } from "@/composables/useAuthSession";
import { ApiError } from "@/services/http";
import { getBeneficiary, getBeneficiaryOptions, updateBeneficiary, type Beneficiary, type BeneficiaryOptions, type BeneficiaryPayload } from "@/services/beneficiarios";
import { createSolicitud, getSolicitudOptions, listSolicitudes, updateSolicitud, changeSolicitudState, type Solicitud, type SolicitudOptions, type SolicitudPayload, type SolicitudUpdatePayload } from "@/services/solicitudes";
import { isAssignmentVigente, listAsignaciones, type Asignacion } from "@/services/tarjetas";
import AsignarTarjetaModal from "@/components/AsignarTarjetaModal.vue";
import LiberarTarjetaModal from "@/components/LiberarTarjetaModal.vue";

const route = useRoute();
const router = useRouter();
const auth = useAuthSession();
const id = Number(route.params.id);
const tab = ref<"general" | "solicitudes" | "tarjetas">("general");
const beneficiary = ref<Beneficiary | null>(null);
const loading = ref(true);
const error = ref("");
const success = ref("");
const saving = ref(false);
const editingGeneral = ref(false);
const generalError = ref("");

const requests = ref<Solicitud[]>([]);
const requestPage = ref(1);
const requestPagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 });
const requestLoading = ref(false);
const requestError = ref("");
const requestOperationError = ref("");

const currentCards = ref<Asignacion[]>([]);
const historicalCards = ref<Asignacion[]>([]);
const currentCardPagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 });
const historicalCardPagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 });
const cardLoading = ref(false);
const cardError = ref("");
const cardsLoaded = ref(false);
const showAssignmentModal = ref(false);
const assignmentRequest = ref<Solicitud | null>(null);
const releaseTarget = ref<Asignacion | null>(null);

const options = ref<SolicitudOptions>({ beneficiarios: [], tiposSolicitud: [], tiposVigencia: [], estadosSolicitud: [], periodos: [] });
const beneficiaryOptions = ref<BeneficiaryOptions>({ tiposBeneficiario: [], carreras: [] });
const showRequestForm = ref(false);
const requestEditing = ref<Solicitud | null>(null);
const requestErrorForm = ref("");
const requestSaving = ref(false);
const requestForm = ref({ idPeriodoAcademico: null as number | null, idTipoSolicitud: null as number | null, idTipoVigencia: 0, fechaInicioSolicitada: "", fechaFinSolicitada: "", motivoSolicitud: "", origenSolicitud: "BACKOFFICE" });
const stateTarget = ref<Solicitud | null>(null);
const stateCode = ref("");
const stateReason = ref("");
const stateError = ref("");
const requestDetail = ref<Solicitud | null>(null);
const generalForm = ref({ primerNombre: "", segundoNombre: "", primerApellido: "", segundoApellido: "", numeroIdentificacion: "", telefonoPrincipal: "", correoPersonal: "", fechaNacimiento: "", idTipoBeneficiario: 0, idCarrera: null as number | null, numeroCuenta: "", correoInstitucional: "", codigoCarne: "", estadoAcademico: "" });

const can = (permission: string) => auth.user.value?.permissions.includes(permission) ?? false;
const canRequests = computed(() => can("SOLICITUDES_CONSULTAR"));
const message = (cause: unknown) => cause instanceof ApiError ? cause.message : "Ocurrió un error inesperado";
const display = (value: unknown) => value === null || value === undefined || value === "" ? "—" : String(value);
const date = (value: string | null | undefined) => value ? value.slice(0, 10) : "—";

const requestColumns: GridColumn[] = [
  { key: "codigoSolicitud", label: "Código", width: "12%" }, { key: "nombreTipoSolicitud", label: "Tipo", width: "13%" },
  { key: "nombrePeriodoAcademico", label: "Período", width: "15%" }, { key: "nombreEstadoSolicitud", label: "Estado", width: "10%" },
  { key: "fechaSolicitud", label: "Solicitada", width: "10%" }, { key: "fechaInicioSolicitada", label: "Inicio", width: "10%" },
  { key: "fechaFinSolicitada", label: "Fin", width: "10%" }, { key: "fechaResolucion", label: "Resolución", width: "10%" }
];
const cardColumns: GridColumn[] = [
  { key: "codigoTarjeta", label: "Identificador", width: "18%" }, { key: "codigoSolicitud", label: "Solicitud", width: "16%" },
  { key: "nombreEstadoAsignacion", label: "Estado", width: "17%" }, { key: "fechaAsignacion", label: "Asignación", width: "15%" },
  { key: "vigencia", label: "Vigencia", width: "22%" }, { key: "fechaDevolucion", label: "Devolución", width: "12%" }, { key: "motivoLiberacion", label: "Motivo liberación", width: "18%" }, { key: "usuarioResponsable", label: "Responsable", width: "14%" }
];
const rows = (value: unknown[]) => value as Record<string, unknown>[];
const requestRow = (item: Solicitud) => ({ ...item, nombreTipoSolicitud: display(item.nombreTipoSolicitud), nombrePeriodoAcademico: display(item.codigoPeriodoAcademico ? `${item.codigoPeriodoAcademico} · ${item.nombrePeriodoAcademico ?? ""}` : item.nombrePeriodoAcademico), fechaSolicitud: date(item.fechaSolicitud), fechaInicioSolicitada: date(item.fechaInicioSolicitada), fechaFinSolicitada: date(item.fechaFinSolicitada), fechaResolucion: date(item.fechaResolucion) });
const cardRow = (item: Asignacion) => ({ ...item, fechaAsignacion: date(item.fechaAsignacion), fechaDevolucion: date(item.fechaDevolucion), motivoLiberacion: display(item.motivoLiberacion), usuarioResponsable: display(item.usuarioResponsable), vigencia: `${date(item.fechaInicioVigencia)} — ${item.fechaFinVigencia ? date(item.fechaFinVigencia) : "Sin vencimiento"}` });

async function loadBeneficiary() {
  loading.value = true; error.value = "";
  try { beneficiary.value = await getBeneficiary(id); if (!beneficiary.value) throw new Error("Beneficiario no encontrado"); fillGeneral(); }
  catch (cause) { error.value = message(cause); }
  finally { loading.value = false; }
}
function fillGeneral() {
  const item = beneficiary.value; if (!item) return;
  generalForm.value = { primerNombre: item.primerNombre, segundoNombre: item.segundoNombre ?? "", primerApellido: item.primerApellido, segundoApellido: item.segundoApellido ?? "", numeroIdentificacion: item.numeroIdentificacion ?? "", telefonoPrincipal: item.telefonoPrincipal ?? "", correoPersonal: item.correoPersonal ?? "", fechaNacimiento: date(item.fechaNacimiento) === "—" ? "" : date(item.fechaNacimiento), idTipoBeneficiario: item.idTipoBeneficiario, idCarrera: item.idCarrera, numeroCuenta: item.numeroCuenta ?? "", correoInstitucional: item.correoInstitucional ?? "", codigoCarne: item.codigoCarne ?? "", estadoAcademico: item.estadoAcademico ?? "" };
}
async function loadRequests(page = 1) {
  if (!canRequests.value) return; requestLoading.value = true; requestError.value = "";
  try { const result = await listSolicitudes("", page, undefined, id); requests.value = result.items; requestPagination.value = result.pagination; requestPage.value = page; }
  catch (cause) { requestError.value = message(cause); }
  finally { requestLoading.value = false; }
}
async function loadCards(currentPage = currentCardPagination.value.page, historicalPage = historicalCardPagination.value.page) {
  if (!can("TARJETAS_CONSULTAR")) return; cardLoading.value = true; cardError.value = "";
  try { const [current, history] = await Promise.all([listAsignaciones(false, id, currentPage), listAsignaciones(true, id, historicalPage)]); currentCards.value = current.items.filter(item => isAssignmentVigente(item.esAsignacionVigente)); historicalCards.value = history.items.filter(item => !isAssignmentVigente(item.esAsignacionVigente)); currentCardPagination.value = current.pagination; historicalCardPagination.value = history.pagination; }
  catch (cause) { cardError.value = message(cause); }
  finally { cardLoading.value = false; cardsLoaded.value = true; }
}
function requestStateCode(item: Pick<Solicitud, "codigoEstadoSolicitud" | "nombreEstadoSolicitud">) { return String(item.codigoEstadoSolicitud || item.nombreEstadoSolicitud || "").trim().toUpperCase(); }
function isApproved(item: Solicitud) { return requestStateCode(item) === "APROBADA"; }
function isPending(item: Solicitud) { return requestStateCode(item) === "PENDIENTE"; }
function currentAssignment(item: Solicitud) { return currentCards.value.find(card => String(card.idSolicitud) === String(item.idSolicitud)) ?? (item.idAsignacionVigente && item.idTarjetaVigente ? { idAsignacion: item.idAsignacionVigente, idTarjeta: item.idTarjetaVigente } : null); }
function openAssignment(item: Solicitud) { assignmentRequest.value = item; showAssignmentModal.value = true; }
function openRequestDetail(item: Solicitud) { requestDetail.value = item; }
function selectTab(next: "general" | "solicitudes" | "tarjetas") { tab.value = next; if (next === "solicitudes" && !requests.value.length) void loadRequests(); if (next === "solicitudes" && !cardsLoaded.value) void loadCards(); if (next === "tarjetas" && !cardsLoaded.value) void loadCards(); }
function assignmentCreated() { const fromRequest = Boolean(assignmentRequest.value); showAssignmentModal.value = false; assignmentRequest.value = null; success.value = "Asignación registrada correctamente."; if (!fromRequest) tab.value = "tarjetas"; void Promise.all([loadRequests(requestPage.value), loadCards()]); }
function releaseCompleted() { releaseTarget.value = null; success.value = "Tarjeta liberada correctamente"; void loadCards(); }
function generalPayload(): BeneficiaryPayload {
  return { person: { primerNombre: generalForm.value.primerNombre, segundoNombre: generalForm.value.segundoNombre || null, primerApellido: generalForm.value.primerApellido, segundoApellido: generalForm.value.segundoApellido || null, numeroIdentificacion: generalForm.value.numeroIdentificacion || null, telefonoPrincipal: generalForm.value.telefonoPrincipal || null, correoPersonal: generalForm.value.correoPersonal || null, fechaNacimiento: generalForm.value.fechaNacimiento ? new Date(`${generalForm.value.fechaNacimiento}T00:00:00`) : null }, beneficiary: { idTipoBeneficiario: generalForm.value.idTipoBeneficiario, idCarrera: generalForm.value.idCarrera, numeroCuenta: generalForm.value.numeroCuenta || null, correoInstitucional: generalForm.value.correoInstitucional || null, codigoCarne: generalForm.value.codigoCarne || null, estadoAcademico: generalForm.value.estadoAcademico || null } } as BeneficiaryPayload;
}
async function saveGeneral() { if (!beneficiary.value || saving.value) return; saving.value = true; generalError.value = ""; success.value = ""; try { beneficiary.value = await updateBeneficiary(id, generalPayload()); editingGeneral.value = false; success.value = "Información actualizada correctamente."; } catch (cause) { generalError.value = message(cause); } finally { saving.value = false; } }
function openRequest(item: Solicitud | null) { requestEditing.value = item; requestErrorForm.value = ""; requestForm.value = { idPeriodoAcademico: item?.idPeriodoAcademico ?? null, idTipoSolicitud: item?.idTipoSolicitud ?? null, idTipoVigencia: item?.idTipoVigencia ?? options.value.tiposVigencia[0]?.idTipoValor ?? 0, fechaInicioSolicitada: item?.fechaInicioSolicitada?.slice(0, 10) ?? "", fechaFinSolicitada: item?.fechaFinSolicitada?.slice(0, 10) ?? "", motivoSolicitud: item?.motivoSolicitud ?? "", origenSolicitud: item?.origenSolicitud ?? "BACKOFFICE" }; showRequestForm.value = true; }
async function saveRequest() { if (requestSaving.value) return; requestSaving.value = true; requestErrorForm.value = ""; success.value = ""; try { const base = { idBeneficiario: id, idPeriodoAcademico: requestForm.value.idPeriodoAcademico, idTipoSolicitud: requestForm.value.idTipoSolicitud, idTipoVigencia: requestForm.value.idTipoVigencia, fechaInicioSolicitada: requestForm.value.fechaInicioSolicitada ? new Date(`${requestForm.value.fechaInicioSolicitada}T00:00:00`) : null, fechaFinSolicitada: requestForm.value.fechaFinSolicitada ? new Date(`${requestForm.value.fechaFinSolicitada}T00:00:00`) : null, motivoSolicitud: requestForm.value.motivoSolicitud || null, origenSolicitud: requestForm.value.origenSolicitud }; let saved: Solicitud | null = null; if (requestEditing.value) await updateSolicitud(requestEditing.value.idSolicitud, base satisfies SolicitudUpdatePayload); else saved = await createSolicitud(base satisfies SolicitudPayload); showRequestForm.value = false; success.value = requestEditing.value ? "Solicitud actualizada correctamente." : `Solicitud creada correctamente. Número de solicitud: ${saved?.codigoSolicitud ?? "—"}`; await loadRequests(requestPage.value); } catch (cause) { requestErrorForm.value = message(cause); } finally { requestSaving.value = false; } }
function changeState(item: Solicitud) { if (!can("SOLICITUDES_GESTIONAR") || !isPending(item)) return; stateTarget.value = item; stateCode.value = ""; stateReason.value = ""; stateError.value = ""; }
async function applyState() { if (!stateTarget.value || !stateCode.value) return; stateError.value = ""; success.value = ""; try { await changeSolicitudState(stateTarget.value.idSolicitud, stateCode.value, stateReason.value.trim() || null, auth.user.value?.username ?? "backoffice"); stateTarget.value = null; success.value = "Estado de solicitud actualizado correctamente."; await loadRequests(requestPage.value); } catch (cause) { stateError.value = message(cause); } }
onMounted(async () => { await auth.restore(); await Promise.all([loadBeneficiary(), getBeneficiaryOptions().then(value => { beneficiaryOptions.value = value; }), getSolicitudOptions().then(value => { options.value = value; })]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración', to: '/' }, { label: 'Operación' }, { label: 'Beneficiarios', to: '/beneficiarios' }, { label: 'Expediente' }]" />
  <div v-if="loading" class="bo-state">Cargando expediente...</div>
  <div v-else-if="error" class="bo-state bo-state-error"><strong>{{ error }}</strong><button class="bo-btn" @click="loadBeneficiary">Reintentar</button></div>
  <template v-else-if="beneficiary">
    <header class="record-header"><div><p class="bo-eyebrow">Operación / Beneficiarios</p><h1>Expediente del beneficiario</h1><p>Consulta integral de información, solicitudes y tarjetas.</p></div><button class="bo-btn" @click="router.push('/beneficiarios')">← Regresar</button></header>
    <section class="beneficiary-identity bo-card"><div class="identity-main"><span class="identity-label">Beneficiario</span><h2>{{ beneficiary.primerNombre }} {{ beneficiary.segundoNombre ?? "" }} {{ beneficiary.primerApellido }} {{ beneficiary.segundoApellido ?? "" }}</h2></div><div><span class="identity-label">Código / cuenta</span><strong>{{ display(beneficiary.codigoCarne ?? beneficiary.numeroCuenta) }}</strong></div><div><span class="identity-label">Tipo</span><strong>{{ display(beneficiary.nombreTipoBeneficiario) }}</strong></div><div><span class="identity-label">Carrera</span><strong>{{ display(beneficiary.nombreCarrera) }}</strong></div><div><span class="identity-label">Estado administrativo</span><span class="status-badge" :class="{ 'status-badge--inactive': !beneficiary.estadoBeneficiario }">{{ beneficiary.estadoBeneficiario ? "Activo" : "Inactivo" }}</span></div></section>
    <div v-if="success" class="bo-notice bo-notice-success" role="status">{{ success }}</div>
    <nav class="beneficiary-detail-tabs" aria-label="Secciones del expediente"><button :class="{ active: tab === 'general' }" @click="selectTab('general')">Información general</button><button v-if="canRequests" :class="{ active: tab === 'solicitudes' }" @click="selectTab('solicitudes')">Solicitudes</button><button v-if="can('TARJETAS_CONSULTAR')" :class="{ active: tab === 'tarjetas' }" @click="selectTab('tarjetas')">Tarjetas asignadas</button></nav>

    <section v-if="tab === 'general'" class="bo-card detail-card"><header class="detail-section-header"><div><h2>Información general</h2><p>Datos personales y administrativos registrados.</p></div><button v-if="can('BENEFICIARIOS_MODIFICAR')" class="bo-btn" @click="editingGeneral = !editingGeneral; generalError = ''">{{ editingGeneral ? "Cancelar" : "Editar información" }}</button></header><p v-if="generalError" class="bo-form-error inline-error">{{ generalError }}</p><form v-if="editingGeneral" class="bo-form" @submit.prevent="saveGeneral"><div class="bo-form-grid"><label>Primer nombre *<input v-model="generalForm.primerNombre" required /></label><label>Segundo nombre<input v-model="generalForm.segundoNombre" /></label><label>Primer apellido *<input v-model="generalForm.primerApellido" required /></label><label>Segundo apellido<input v-model="generalForm.segundoApellido" /></label><label>Identificación<input v-model="generalForm.numeroIdentificacion" /></label><label>Fecha de nacimiento<input v-model="generalForm.fechaNacimiento" type="date" /></label><label>Teléfono<input v-model="generalForm.telefonoPrincipal" /></label><label>Correo personal<input v-model="generalForm.correoPersonal" type="email" /></label><label>Tipo de beneficiario *<select v-model.number="generalForm.idTipoBeneficiario" required><option v-for="item in beneficiaryOptions.tiposBeneficiario" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.codigoTipoValor }} · {{ item.nombreTipoValor }}</option></select></label><label>Carrera<select v-model="generalForm.idCarrera"><option :value="null">Sin carrera</option><option v-for="item in beneficiaryOptions.carreras" :key="item.idCarrera" :value="item.idCarrera">{{ item.codigoCarrera }} · {{ item.nombreCarrera }}</option></select></label><label>Código de beneficiario<input v-model="generalForm.codigoCarne" /></label><label>Número de cuenta<input v-model="generalForm.numeroCuenta" /></label><label>Correo institucional<input v-model="generalForm.correoInstitucional" /></label><label>Estado académico<input v-model="generalForm.estadoAcademico" /></label></div><div class="form-actions"><button class="bo-btn bo-btn-primary" :disabled="saving">{{ saving ? "Guardando..." : "Guardar cambios" }}</button></div></form><dl v-else class="beneficiary-details-grid"><div><dt>Nombre completo</dt><dd>{{ beneficiary.primerNombre }} {{ beneficiary.segundoNombre ?? "" }} {{ beneficiary.primerApellido }} {{ beneficiary.segundoApellido ?? "" }}</dd></div><div><dt>Identificación</dt><dd>{{ display(beneficiary.numeroIdentificacion) }}</dd></div><div><dt>Código de beneficiario</dt><dd>{{ display(beneficiary.codigoCarne) }}</dd></div><div><dt>Número de cuenta</dt><dd>{{ display(beneficiary.numeroCuenta) }}</dd></div><div><dt>Tipo</dt><dd>{{ display(beneficiary.nombreTipoBeneficiario) }}</dd></div><div><dt>Carrera</dt><dd>{{ display(beneficiary.nombreCarrera) }}</dd></div><div><dt>Correo personal</dt><dd>{{ display(beneficiary.correoPersonal) }}</dd></div><div><dt>Correo institucional</dt><dd>{{ display(beneficiary.correoInstitucional) }}</dd></div><div><dt>Teléfono</dt><dd>{{ display(beneficiary.telefonoPrincipal) }}</dd></div><div><dt>Fecha de nacimiento</dt><dd>{{ date(beneficiary.fechaNacimiento) }}</dd></div><div><dt>Estado académico</dt><dd>{{ display(beneficiary.estadoAcademico) }}</dd></div><div><dt>Estado administrativo</dt><dd><span class="status-badge" :class="{ 'status-badge--inactive': !beneficiary.estadoBeneficiario }">{{ beneficiary.estadoBeneficiario ? "Activo" : "Inactivo" }}</span></dd></div></dl></section>

       <section v-else-if="tab === 'solicitudes'" class="bo-card detail-card"><header class="detail-section-header"><div><h2>Solicitudes</h2><p>Solicitudes vinculadas únicamente a este beneficiario.</p></div><button v-if="can('SOLICITUDES_REGISTRAR')" class="bo-btn bo-btn-primary" @click="openRequest(null)">Nueva solicitud</button></header><DataGrid class="beneficiary-requests-grid" :columns="requestColumns" :rows="rows(requests.map(requestRow))" :row-key="row => String(row.idSolicitud)" :pagination="requestPagination" :loading="requestLoading" :error="requestError" empty-text="No hay solicitudes para este beneficiario." @page="loadRequests"><template #actions="{ row }"><button class="bo-action" @click="openRequestDetail(row as unknown as Solicitud)">Ver comentarios</button><button v-if="can('SOLICITUDES_MODIFICAR') && isPending(row as unknown as Solicitud)" class="bo-action" @click="openRequest(row as unknown as Solicitud)">Editar</button><button v-if="can('TARJETAS_ASIGNAR') && can('TARJETAS_CONSULTAR') && isApproved(row as unknown as Solicitud) && !currentAssignment(row as unknown as Solicitud)" class="bo-action" @click="openAssignment(row as unknown as Solicitud)">Asignar tarjeta</button><button v-if="can('TARJETAS_CONSULTAR') && currentAssignment(row as unknown as Solicitud)" class="bo-action" @click="router.push(`/tarjetas/${currentAssignment(row as unknown as Solicitud)?.idTarjeta}/gestionar?beneficiario=${id}`)">Consultar tarjeta</button><button v-if="can('SOLICITUDES_GESTIONAR') && isPending(row as unknown as Solicitud)" class="bo-action" @click="changeState(row as unknown as Solicitud)">Aprobar / rechazar</button></template></DataGrid></section>

      <section v-else class="cards-tab"><div class="section-intro"><div><h2>Tarjetas asignadas</h2><p>Se separan las asignaciones vigentes del historial de devoluciones o reemplazos.</p></div><button v-if="can('TARJETAS_ASIGNAR') && can('TARJETAS_CONSULTAR')" class="bo-btn bo-btn-primary" @click="showAssignmentModal = true">Asignar tarjeta</button></div><div v-if="cardError" class="bo-state bo-state-error card-error"><strong>{{ cardError }}</strong><button class="bo-btn" @click="loadCards()">Reintentar</button></div><template v-else><section class="bo-card detail-card card-group"><h3>Tarjetas vigentes</h3><DataGrid :columns="cardColumns" :rows="rows(currentCards.map(cardRow))" :pagination="currentCardPagination" :loading="cardLoading" empty-text="No hay tarjetas vigentes para este beneficiario." @page="page => loadCards(page, historicalCardPagination.page)"><template #actions="{ row }"><button v-if="can('TARJETAS_DESACTIVAR')" class="bo-action" @click="releaseTarget = currentCards.find(item => String(item.idAsignacion) === String(row.idAsignacion)) ?? null">Liberar tarjeta</button><button class="bo-action" @click="router.push(`/tarjetas/${row.idTarjeta}/gestionar?beneficiario=${id}`)">Ver / Gestionar</button></template></DataGrid></section><section class="bo-card detail-card card-group"><h3>Tarjetas históricas</h3><DataGrid :columns="cardColumns" :rows="rows(historicalCards.map(cardRow))" :pagination="historicalCardPagination" :loading="cardLoading" empty-text="No hay tarjetas históricas para este beneficiario." @page="page => loadCards(currentCardPagination.page, page)"><template #actions="{ row }"><button class="bo-action" @click="router.push(`/tarjetas/${row.idTarjeta}/gestionar?beneficiario=${id}`)">Ver / Gestionar</button></template></DataGrid></section></template></section>
   </template>
     <AsignarTarjetaModal v-if="showAssignmentModal && beneficiary" :beneficiary="beneficiary" :can-create-request="can('SOLICITUDES_REGISTRAR')" :initial-request="assignmentRequest" @close="showAssignmentModal = false; assignmentRequest = null" @assigned="assignmentCreated" @create-request="showAssignmentModal = false; assignmentRequest = null; tab = 'solicitudes'; openRequest(null)" />
    <LiberarTarjetaModal v-if="releaseTarget && beneficiary" :assignment="releaseTarget" :beneficiary="beneficiary" @close="releaseTarget = null" @released="releaseCompleted" />

  <div v-if="requestDetail" class="bo-modal-backdrop" @click.self="requestDetail = null"><section class="bo-modal"><header><h2>Detalle de solicitud</h2><button class="bo-close" type="button" @click="requestDetail = null">×</button></header><dl class="request-detail"><div><dt>Solicitud</dt><dd>{{ requestDetail.codigoSolicitud }}</dd></div><div><dt>Estado</dt><dd>{{ requestDetail.nombreEstadoSolicitud }}</dd></div><div><dt>Motivo original</dt><dd>{{ display(requestDetail.motivoSolicitud) }}</dd></div><div><dt>Observación de resolución</dt><dd>{{ display(requestDetail.observacionResolucion) }}</dd></div><div><dt>Fecha de resolución</dt><dd>{{ date(requestDetail.fechaResolucion) }}</dd></div><div><dt>Usuario responsable</dt><dd>{{ display(requestDetail.nombreUsuarioResolucion ?? requestDetail.idUsuarioResolucion) }}</dd></div></dl><footer><button class="bo-btn" type="button" @click="requestDetail = null">Cerrar</button></footer></section></div>
    <div v-if="showRequestForm" class="bo-modal-backdrop" @click.self="showRequestForm = false"><section class="bo-modal"><header><h2>{{ requestEditing ? "Editar solicitud" : "Nueva solicitud" }}</h2><button class="bo-close" type="button" @click="showRequestForm = false">×</button></header><form class="bo-form" @submit.prevent="saveRequest"><p class="bo-form-note">Beneficiario: <strong>{{ beneficiary?.primerNombre }} {{ beneficiary?.primerApellido }}</strong></p><p v-if="!requestEditing" class="bo-form-note">Número de solicitud: <strong>Se asignará automáticamente al guardar</strong></p><label>Tipo de solicitud<select v-model="requestForm.idTipoSolicitud"><option :value="null">Sin tipo</option><option v-for="item in options.tiposSolicitud" :key="item.idTipoSolicitud" :value="item.idTipoSolicitud">{{ item.nombreTipoSolicitud }}</option></select></label><label>Período académico<select v-model="requestForm.idPeriodoAcademico"><option :value="null">Sin período</option><option v-for="item in options.periodos" :key="item.idPeriodoAcademico" :value="item.idPeriodoAcademico">{{ item.codigoPeriodoAcademico }} · {{ item.nombrePeriodoAcademico }}</option></select></label><label>Tipo de vigencia *<select v-model.number="requestForm.idTipoVigencia" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.tiposVigencia" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Inicio<input v-model="requestForm.fechaInicioSolicitada" type="date" /></label><label>Fin<input v-model="requestForm.fechaFinSolicitada" type="date" /></label><label>Motivo<textarea v-model="requestForm.motivoSolicitud" /></label><p v-if="requestErrorForm" class="bo-form-error">{{ requestErrorForm }}</p><footer><button type="button" class="bo-btn" @click="showRequestForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="requestSaving">{{ requestSaving ? "Guardando..." : "Guardar" }}</button></footer></form></section></div>
   <div v-if="stateTarget" class="bo-modal-backdrop" @click.self="stateTarget = null"><section class="bo-modal"><header><h2>Aprobar o rechazar solicitud</h2><button class="bo-close" type="button" @click="stateTarget = null">×</button></header><p>Solicitud: {{ stateTarget.codigoSolicitud }}</p><label class="modal-label">Resultado<select v-model="stateCode" required><option value="" disabled>Seleccione...</option><option v-for="item in options.estadosSolicitud.filter(value => ['APROBADA','RECHAZADA'].includes(value.codigoTipoValor.trim().toUpperCase()))" :key="item.idTipoValor" :value="item.codigoTipoValor">{{ item.nombreTipoValor }}</option></select></label><textarea v-model="stateReason" placeholder="Motivo u observación de resolución" /><p v-if="stateError" class="bo-form-error">{{ stateError }}</p><footer><button class="bo-btn" @click="stateTarget = null">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="!stateCode" @click="applyState">Confirmar</button></footer></section></div>
